import time
from typing import List, Union

from ...analysis.person_selector import PersonSelection
from ...data.constants import ALL_SELECTED_FRAMES_KEY, ALL_SELECTED_PERSONS_KEY
from ...output.image_writer import ImageWriter
from .base import PipelineStep


class OutputGenerationStep(PipelineStep):
    """Pipeline step for generating output files with dual input support."""

    @property
    def step_name(self) -> str:
        return "output_generation"

    def execute(self) -> None:
        """Generate output files for selected frames or persons."""
        self._state.start_step(self.step_name)

        try:
            # Step 1: Input Type Detection
            input_data, input_type = self._detect_input_type()

            if not input_data:
                self._handle_no_input_data()
                return

            # Step 2: Process based on input type
            if input_type == "person_selection":
                self._process_person_selections(input_data)
            else:  # input_type == "frame_selection"
                self._process_frame_selections(input_data)

        except Exception as e:
            self.logger.error(f"❌ Output generation failed: {e}")
            self._state.fail_step(self.step_name, str(e))
            raise

    def _detect_input_type(self) -> tuple[Union[List[PersonSelection], List[str]], str]:
        """Detect input type and return (data, type).

        Returns:
            Tuple of (input_data, input_type) where input_type is
            "person_selection" or "frame_selection"
        """
        # Priority 1: Check for PersonSelection data (person-based pipeline)
        person_selection_progress = self._state.get_step_progress("person_selection")
        if person_selection_progress:
            serializable_persons = person_selection_progress.get_data(
                ALL_SELECTED_PERSONS_KEY, []
            )
            if serializable_persons:
                # Reconstruct PersonSelection objects from serializable data
                person_selections = self._reconstruct_person_selections(
                    serializable_persons
                )
                return person_selections, "person_selection"

        # Priority 2: Check for frame selection data (backwards compatibility)
        frame_selection_progress = self._state.get_step_progress("frame_selection")
        if frame_selection_progress:
            selected_frame_ids = frame_selection_progress.get_data(
                ALL_SELECTED_FRAMES_KEY, []
            )
            if selected_frame_ids:
                return selected_frame_ids, "frame_selection"

        # No input data found
        return [], "none"

    def _reconstruct_person_selections(
        self, serializable_persons: List[dict]
    ) -> List[PersonSelection]:
        """Reconstruct PersonSelection objects from serializable data.

        Args:
            serializable_persons: List of dictionaries containing person selection data
                                 or actual PersonSelection objects (for testing)

        Returns:
            List of PersonSelection objects
        """
        from ...analysis.person_selector import PersonSelection

        # Handle case where PersonSelection objects are passed directly (for tests)
        if serializable_persons and isinstance(
            serializable_persons[0], PersonSelection
        ):
            return serializable_persons

        # Create lookup map for frames and persons
        frames_map = {frame.frame_id: frame for frame in self._state.frames}

        person_selections = []
        for data in serializable_persons:
            frame_id = data["frame_id"]
            person_id = data["person_id"]

            if frame_id not in frames_map:
                self.logger.warning(
                    f"Frame {frame_id} not found, skipping person selection"
                )
                continue

            frame_data = frames_map[frame_id]

            # Find the person in the frame
            person = None
            if hasattr(frame_data, "persons") and frame_data.persons:
                for p in frame_data.persons:
                    if p.person_id == person_id:
                        person = p
                        break

            if person is None:
                self.logger.warning(
                    f"Person {person_id} not found in frame {frame_id}, skipping"
                )
                continue

            # Reconstruct PersonSelection object
            selection = PersonSelection(
                frame_data=frame_data,
                person_id=person_id,
                person=person,
                selection_score=data["selection_score"],
                category=data["category"],
            )
            person_selections.append(selection)

        return person_selections

    def _handle_no_input_data(self) -> None:
        """Handle case where no input data is available."""
        if self.formatter:
            self.formatter.print_warning(
                "No frames or persons selected for output generation"
            )
        else:
            self.logger.warning(
                "⚠️ No frames or persons selected for output generation"
            )
        self._state.get_step_progress(self.step_name).start(0)

    def _process_person_selections(
        self, person_selections: List[PersonSelection]
    ) -> None:
        """Process PersonSelection objects for output generation."""
        if self.formatter:
            self.formatter.print_info("👥 Creating person-based outputs...", "persons")
        else:
            self.logger.info(
                f"👥 Generating person-based output for {len(person_selections)} persons..."
            )

        # Calculate expected total files based on configuration
        total_expected_files = self._calculate_expected_files_count(person_selections)
        self._state.get_step_progress(self.step_name).start(total_expected_files)

        output_dir = self.pipeline.context.output_directory
        image_writer = ImageWriter(context=self.pipeline.context)
        all_output_files = []
        step_start_time = time.time()

        def progress_callback(files_generated_count):
            self._check_interrupted()
            self._state.update_step_progress(self.step_name, files_generated_count)
            if self.formatter:
                # Calculate rate
                elapsed = time.time() - step_start_time
                rate = files_generated_count / elapsed if elapsed > 0 else 0
                self.formatter.update_progress(1, rate=rate)

        if self.formatter:
            with self.formatter.create_progress_bar(
                f"Saving images to {output_dir}", total_expected_files
            ):
                for i, person_selection in enumerate(person_selections):
                    # Check for interruption at regular intervals
                    if i % 5 == 0:
                        self._check_interrupted()

                    try:
                        output_files = self._generate_output_for_person_selection(
                            person_selection, image_writer
                        )
                        all_output_files.extend(output_files)

                        # Update progress with actual files generated so far
                        progress_callback(len(all_output_files))
                    except Exception as e:
                        self.logger.warning(
                            f"⚠️ Failed to generate output for person {person_selection.person_id}: {e}"
                        )
                        continue
        else:
            for i, person_selection in enumerate(person_selections):
                # Check for interruption at regular intervals
                if i % 5 == 0:
                    self._check_interrupted()

                try:
                    output_files = self._generate_output_for_person_selection(
                        person_selection, image_writer
                    )
                    all_output_files.extend(output_files)

                    # Update progress with actual files generated so far
                    progress_callback(len(all_output_files))
                except Exception as e:
                    self.logger.warning(
                        f"⚠️ Failed to generate output for person {person_selection.person_id}: {e}"
                    )
                    continue

        self._finalize_output_generation(all_output_files, output_dir, "person-based")

    def _calculate_expected_files_count(
        self, person_selections: List[PersonSelection]
    ) -> int:
        """Calculate expected number of files to be generated based on configuration.

        Args:
            person_selections: List of PersonSelection objects

        Returns:
            Estimated total number of files that will be generated
        """
        if not person_selections:
            return 0

        # Get configuration from pipeline context
        config = self.pipeline.context.config

        # Calculate files per person based on configuration
        files_per_person = 0

        # Face crop (if face_crop_enabled and person has face detection)
        if config.output.image.face_crop_enabled:
            files_per_person += 1

        # Body crop (if enable_pose_cropping and person has body detection)
        if config.output.image.enable_pose_cropping:
            files_per_person += 1

        # Full frame (if enable_pose_cropping is False OR full_frames is True)
        if (
            not config.output.image.enable_pose_cropping
            or config.output.image.full_frames
        ):
            files_per_person += 1

        # Estimate total files
        estimated_total = len(person_selections) * files_per_person

        self.logger.debug(
            f"Expected files calculation: {len(person_selections)} persons × "
            f"{files_per_person} files/person = {estimated_total} total files"
        )

        return estimated_total

    def _process_frame_selections(self, selected_frame_ids: List[str]) -> None:
        """Process frame IDs for output generation (backwards compatibility)."""
        # Map IDs to the actual FrameData objects
        all_frames_map = {frame.frame_id: frame for frame in self._state.frames}
        selected_frames = [
            all_frames_map[fid] for fid in selected_frame_ids if fid in all_frames_map
        ]

        if not selected_frames:
            self._handle_no_input_data()
            return

        output_dir = self.pipeline.context.output_directory
        image_writer = ImageWriter(context=self.pipeline.context)

        if self.formatter:
            self.formatter.print_info("📁 Creating output files...", "files")
        else:
            self.logger.info(f"📁 Generating output in {output_dir}...")

        total_frames = len(selected_frames)
        self._state.get_step_progress(self.step_name).start(total_frames)

        all_output_files = []
        step_start_time = time.time()

        def progress_callback(processed_count):
            self._check_interrupted()
            self._state.update_step_progress(self.step_name, processed_count)
            if self.formatter:
                # Calculate rate
                elapsed = time.time() - step_start_time
                rate = processed_count / elapsed if elapsed > 0 else 0
                self.formatter.update_progress(1, rate=rate)

        if self.formatter:
            with self.formatter.create_progress_bar("Generating files", total_frames):
                for i, frame in enumerate(selected_frames):
                    # Check for interruption at regular intervals
                    if i % 5 == 0:
                        self._check_interrupted()

                    output_files = image_writer.save_frame_outputs(frame)
                    all_output_files.extend(output_files)
                    progress_callback(i + 1)
        else:
            for i, frame in enumerate(selected_frames):
                # Check for interruption at regular intervals
                if i % 5 == 0:
                    self._check_interrupted()

                output_files = image_writer.save_frame_outputs(frame)
                all_output_files.extend(output_files)
                progress_callback(i + 1)

        self._finalize_output_generation(all_output_files, output_dir, "frame-based")

    def _generate_output_for_person_selection(
        self, person_selection: PersonSelection, image_writer: ImageWriter
    ) -> List[str]:
        """Generate output files for a single PersonSelection.

        Args:
            person_selection: PersonSelection object containing frame and person data
            image_writer: ImageWriter instance for file generation

        Returns:
            List of generated output file paths
        """
        # Use person-specific output generation
        return image_writer.save_person_outputs(person_selection)

    def _finalize_output_generation(
        self, all_output_files: List[str], output_dir, generation_type: str
    ) -> None:
        """Finalize output generation with statistics and logging.

        Args:
            all_output_files: List of generated output file paths
            output_dir: Output directory path
            generation_type: Type of generation ("person-based" or "frame-based")
        """
        self._state.processing_stats["output_files"] = all_output_files
        self._state.processing_stats["total_output_files"] = len(all_output_files)

        if self.formatter:
            self._state.get_step_progress(self.step_name).set_data(
                "step_results",
                {
                    "files_generated": f"✅ Generated {len(all_output_files)} files ({generation_type})",
                    "location_info": f"📂 Location: {output_dir}",
                },
            )
        else:
            self.logger.info(
                f"✅ Output generation completed: {len(all_output_files)} files ({generation_type}) in {output_dir}"
            )

from ...analysis.frame_selector import SelectionCriteria, create_frame_selector
from ...data.constants import ALL_SELECTED_FRAMES_KEY
from .base import PipelineStep


class FrameSelectionStep(PipelineStep):
    """Pipeline step for selecting the best frames."""

    @property
    def step_name(self) -> str:
        return "frame_selection"

    def _calculate_dynamic_max_frames(
        self, baseline_frames: int, video_duration: float
    ) -> int:
        """Calculate dynamic max frames per category based on video duration.

        Uses baseline minimum frames for 30s video, increments by 1 for every 10 additional seconds after 30s.
        Result is capped by max_frames_per_category configuration.

        Args:
            baseline_frames: Base minimum number of frames for 30s video
            video_duration: Video duration in seconds

        Returns:
            Dynamic max frames per category (baseline + duration scaling, capped by config)
        """
        additional_frames = max(0, int((video_duration - 30.0) // 10))
        calculated_frames = baseline_frames + additional_frames

        # Respect the max_frames_per_category configuration limit
        max_allowed = self.config.output.max_frames_per_category
        return min(calculated_frames, max_allowed)

    def execute(self) -> None:
        """Select best frames based on quality and diversity."""
        self._state.start_step(self.step_name)

        try:
            candidate_frames = [
                f
                for f in self._state.frames
                if (f.has_faces() or f.has_poses()) and f.quality_metrics is not None
            ]

            if not candidate_frames:
                if self.formatter:
                    self.formatter.print_warning(
                        "No frames with quality assessments for selection"
                    )
                else:
                    self.logger.warning(
                        "⚠️ No frames with quality assessments for selection"
                    )
                self._state.get_step_progress(self.step_name).start(0)
                return

            total_candidates = len(candidate_frames)
            if self.formatter:
                self.formatter.print_info(
                    "🎯 Optimizing frame selection...", "targeting"
                )
            else:
                self.logger.info(f"🎯 Selecting from {total_candidates} candidates...")

            # Calculate dynamic frames per category based on video duration
            baseline_frames = self.config.output.min_frames_per_category
            video_duration = self._state.video_metadata.duration
            dynamic_max_frames = self._calculate_dynamic_max_frames(
                baseline_frames, video_duration
            )

            criteria = SelectionCriteria(
                min_frames_per_category=self.config.output.min_frames_per_category,
                max_frames_per_category=dynamic_max_frames,
                min_quality_threshold=self.config.frame_selection.min_quality_threshold,
                face_size_weight=self.config.frame_selection.face_size_weight,
                quality_weight=self.config.frame_selection.quality_weight,
                diversity_threshold=self.config.frame_selection.diversity_threshold,
                temporal_diversity_threshold=self.config.frame_selection.temporal_diversity_threshold,
            )
            frame_selector = create_frame_selector(criteria)
            self._state.get_step_progress(self.step_name).start(total_candidates)

            current_progress = 0

            def progress_callback(message: str):
                nonlocal current_progress
                self._check_interrupted()
                # Simplified progress update
                current_progress += 1
                self._state.update_step_progress(self.step_name, current_progress)
                if self.formatter:
                    self.formatter.update_progress(1)

            if self.formatter:
                with self.formatter.create_progress_bar(
                    "Selecting frames", total_candidates
                ):
                    selection_summary = frame_selector.select_best_frames(
                        candidate_frames,
                        progress_callback,
                        interruption_check=self._check_interrupted,
                    )
            else:
                selection_summary = frame_selector.select_best_frames(
                    candidate_frames,
                    lambda m: self.logger.debug(f"   {m}"),
                    interruption_check=self._check_interrupted,
                )

            self._state.update_step_progress(
                self.step_name, total_candidates
            )  # Mark as complete

            # Store detailed summary and high-level selections
            self._store_selection_results(selection_summary, criteria)
            self._format_and_log_results(selection_summary)

        except Exception as e:
            self.logger.error(f"❌ Frame selection failed: {e}")
            self._state.fail_step(self.step_name, str(e))
            raise

    def _store_selection_results(self, selection_summary, criteria):
        """Stores detailed and high-level selection results in the pipeline state."""
        frame_selections = {
            "summary": {
                "total_candidates": selection_summary.total_candidates,
                "total_selected": selection_summary.total_selected,
                "selection_criteria": criteria.__dict__,
            },
            "pose_categories": {},
            "head_angle_categories": {},
        }

        # Process and store pose selections
        for category, selection in selection_summary.pose_selections.items():
            if selection.selected_frames:
                frame_selections["pose_categories"][category] = {
                    "selected_count": len(selection.selected_frames),
                    "total_candidates": selection.total_candidates,
                    "rationale": selection.selection_rationale,
                    "quality_stats": {
                        "range": selection.quality_range,
                        "average": selection.average_quality,
                    },
                }

        # Process and store head angle selections
        for category, selection in selection_summary.head_angle_selections.items():
            if selection.selected_frames:
                frame_selections["head_angle_categories"][category] = {
                    "selected_count": len(selection.selected_frames),
                    "total_candidates": selection.total_candidates,
                    "rationale": selection.selection_rationale,
                    "quality_stats": {
                        "range": selection.quality_range,
                        "average": selection.average_quality,
                    },
                }

        self._state.get_step_progress(self.step_name).set_data(
            "frame_selections", frame_selections
        )

        # Store a flat list of all selected frames for the next step
        all_selected_frames = []
        for _, selection in selection_summary.pose_selections.items():
            all_selected_frames.extend(selection.selected_frames)
        for _, selection in selection_summary.head_angle_selections.items():
            all_selected_frames.extend(selection.selected_frames)

        # Remove duplicates
        unique_frames_map = {frame.frame_id: frame for frame in all_selected_frames}
        unique_frame_ids = list(unique_frames_map.keys())
        self._state.get_step_progress(self.step_name).set_data(
            ALL_SELECTED_FRAMES_KEY, unique_frame_ids
        )

    def _format_and_log_results(self, selection_summary):
        """Formats the results for display and logs them."""
        if self.formatter:
            body_poses = [
                f"{cat} ({len(sel.selected_frames)})"
                for cat, sel in selection_summary.pose_selections.items()
                if sel.selected_frames
            ]
            head_angles = [
                f"{cat} ({len(sel.selected_frames)})"
                for cat, sel in selection_summary.head_angle_selections.items()
                if sel.selected_frames
            ]

            results = {
                "candidates_summary": f"📊 Candidates: {selection_summary.total_candidates} frames",
                "selected_summary": f"✅ Selected {selection_summary.total_selected} frames",
                "body_poses_breakdown": (
                    f"🏃 Body poses: {', '.join(body_poses)}"
                    if body_poses
                    else "🏃 No body poses selected"
                ),
                "head_angles_breakdown": (
                    f"👤 Head angles: {', '.join(head_angles)}"
                    if head_angles
                    else "👤 No head angles selected"
                ),
            }
            self._state.get_step_progress(self.step_name).set_data(
                "step_results", results
            )
        else:
            self.logger.info(
                f"✅ Frame selection completed: {selection_summary.total_selected} frames from {selection_summary.total_candidates} candidates"
            )
            if selection_summary.total_selected == 0:
                self.logger.warning(
                    "⚠️  No frames were selected - check quality thresholds!"
                )

def has_faces(self) -> bool:
    """Check if frame has any face detections."""
    return len(self.face_detections) > 0

def has_poses(self) -> bool:
    """Check if frame has any pose detections."""
    return len(self.pose_detections) > 0

def has_head_poses(self) -> bool:
    """Check if frame has any head pose results."""
    return len(self.head_poses) > 0

def has_closeup_detections(self) -> bool:
    """Check if frame has any closeup detections."""
    return len(self.closeup_detections) > 0

def get_best_face(self) -> Optional[FaceDetection]:
    """Get face detection with highest confidence."""
    if not self.face_detections:
        return None
    return max(self.face_detections, key=lambda f: f.confidence)

def get_best_pose(self) -> Optional[PoseDetection]:
    """Get pose detection with highest confidence."""
    if not self.pose_detections:
        return None
    return max(self.pose_detections, key=lambda p: p.confidence)

def get_best_head_pose(self) -> Optional[HeadPoseResult]:
    """Get head pose result with highest confidence."""
    if not self.head_poses:
        return None
    return max(self.head_poses, key=lambda h: h.confidence)

def get_best_closeup(self) -> Optional[CloseupDetection]:
    """Get closeup detection with highest confidence."""
    if not self.closeup_detections:
        return None
    return max(self.closeup_detections, key=lambda c: c.confidence)

def get_persons(self) -> List["Person"]:
    """Get list of persons detected in the frame."""
    return self.persons

def get_pose_classifications(self) -> List[str]:
    """Get all unique pose classifications."""
    classifications = []
    for pose in self.pose_detections:
        for classification, _ in pose.pose_classifications:
            if classification not in classifications:
                classifications.append(classification)
    return classifications

def get_head_directions(self) -> List[str]:
    """Get all unique head directions."""
    directions = []
    for head_pose in self.head_poses:
        if head_pose.direction and head_pose.direction not in directions:
            directions.append(head_pose.direction)
    return directions

def has_pose_classification(self, classification: str) -> bool:
    """Check if frame has specific pose classification."""
    return classification in self.get_pose_classifications()

def has_head_direction(self, direction: str) -> bool:
    """Check if frame has specific head direction."""
    return direction in self.get_head_directions()

def get_shot_types(self) -> List[str]:
    """Get all unique shot types from closeup detections."""
    shot_types = []
    for closeup in self.closeup_detections:
        if closeup.shot_type and closeup.shot_type not in shot_types:
            shot_types.append(closeup.shot_type)
    return shot_types

def has_shot_type(self, shot_type: str) -> bool:
    """Check if frame has specific shot type."""
    return shot_type in self.get_shot_types()

def is_closeup_shot(self) -> bool:
    """Check if frame is classified as any type of closeup shot."""
    for closeup in self.closeup_detections:
        if closeup.is_closeup:
            return True
    return False

def is_high_quality(self) -> bool:
    """Check if frame meets high quality standards."""
    return self.quality_metrics is not None and self.quality_metrics.is_high_quality

"""Data structures for AI model outputs.

This module defines data classes for storing detection results from face detection,
pose estimation, and head pose estimation models.
"""

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from .constants import QualityMethod


@dataclass
class FaceDetection:
    """Face detection result containing bounding box and landmarks."""

    bbox: Tuple[int, int, int, int]  # (x1, y1, x2, y2)
    confidence: float
    landmarks: Optional[List[Tuple[float, float]]] = None  # List of (x, y) coordinates

    def __post_init__(self) -> None:
        """Validate bbox format and confidence range."""
        if len(self.bbox) != 4:
            raise ValueError("bbox must contain exactly 4 values (x1, y1, x2, y2)")
        if not (0.0 <= self.confidence <= 1.0):
            raise ValueError("confidence must be between 0.0 and 1.0")

    @property
    def width(self) -> int:
        """Get width of face bounding box."""
        return self.bbox[2] - self.bbox[0]

    @property
    def height(self) -> int:
        """Get height of face bounding box."""
        return self.bbox[3] - self.bbox[1]

    @property
    def area(self) -> int:
        """Get area of face bounding box."""
        return self.width * self.height

    @property
    def center(self) -> Tuple[float, float]:
        """Get center point of face bounding box."""
        return ((self.bbox[0] + self.bbox[2]) / 2, (self.bbox[1] + self.bbox[3]) / 2)


@dataclass
class PoseDetection:
    """Body pose detection result containing keypoints and classification."""

    bbox: Tuple[int, int, int, int]  # (x1, y1, x2, y2)
    confidence: float
    keypoints: Dict[
        str, Tuple[float, float, float]
    ]  # {keypoint_name: (x, y, confidence)}
    pose_classifications: List[Tuple[str, float]] = field(default_factory=list)

    def __post_init__(self) -> None:
        """Validate detection data."""
        if len(self.bbox) != 4:
            raise ValueError("bbox must contain exactly 4 values (x1, y1, x2, y2)")
        if not (0.0 <= self.confidence <= 1.0):
            raise ValueError("confidence must be between 0.0 and 1.0")
        for _, confidence in self.pose_classifications:
            if not (0.0 <= confidence <= 1.0):
                raise ValueError("pose_confidence must be between 0.0 and 1.0")

    def get_keypoint(self, name: str) -> Optional[Tuple[float, float, float]]:
        """Get specific keypoint by name."""
        return self.keypoints.get(name)

    def has_keypoint(self, name: str) -> bool:
        """Check if keypoint exists and has sufficient confidence."""
        keypoint = self.keypoints.get(name)
        return keypoint is not None and keypoint[2] > 0.5

    @property
    def valid_keypoints(self) -> Dict[str, Tuple[float, float, float]]:
        """Get keypoints with confidence > 0.5."""
        return {name: kp for name, kp in self.keypoints.items() if kp[2] > 0.5}

    @property
    def center(self) -> Tuple[float, float]:
        """Get center point of body bounding box."""
        return ((self.bbox[0] + self.bbox[2]) / 2, (self.bbox[1] + self.bbox[3]) / 2)


@dataclass
class HeadPoseResult:
    """Head pose estimation result containing orientation angles."""

    yaw: float  # Rotation around vertical axis
    pitch: float  # Rotation around horizontal axis (nodding)
    roll: float  # Rotation around depth axis (tilting)
    confidence: float
    face_id: int = 0  # Index of face in frame
    direction: Optional[str] = None  # Classified cardinal direction
    direction_confidence: Optional[
        float
    ] = None  # Confidence of direction classification

    def __post_init__(self) -> None:
        """Validate angle ranges and confidence."""
        if not (0.0 <= self.confidence <= 1.0):
            raise ValueError("confidence must be between 0.0 and 1.0")
        if self.direction_confidence is not None and not (
            0.0 <= self.direction_confidence <= 1.0
        ):
            raise ValueError("direction_confidence must be between 0.0 and 1.0")

        # Angles can be outside typical ranges, but warn about extreme values
        if abs(self.yaw) > 180 or abs(self.pitch) > 90 or abs(self.roll) > 180:
            import warnings

            warnings.warn(
                f"Extreme angle values detected: yaw={self.yaw}, pitch={self.pitch}, roll={self.roll}",
                stacklevel=2,
            )

    @property
    def is_valid_orientation(self) -> bool:
        """Check if head orientation is valid (not excessively tilted)."""
        return abs(self.roll) <= 30.0  # Max acceptable tilt

    @property
    def angles_dict(self) -> Dict[str, float]:
        """Get angles as dictionary."""
        return {"yaw": self.yaw, "pitch": self.pitch, "roll": self.roll}


